export const LX_STATION_STEPS = Object.freeze({"ad-amr-fleet-traffic-and-estop-drill":[{"id":"ppe","title":"Dress for the floor","cue":"Hi-vis vest, safety shoes and safety glasses before you step onto the floor."},{"id":"brief","title":"Read the traffic plan","cue":"Find today's lanes, crossings and closed zones before walking onto the floor."},{"id":"cross-lane","title":"Cross at the marked point","cue":"Walk to the marked crossing, look both ways and cross."},{"id":"estop-drill","title":"Run the e-stop drill","cue":"Trigger the drill and confirm each robot on the lane has actually stopped."},{"id":"scanner-check","title":"Check the unit's scanner field","cue":"Read the scanner field check and commit only in the green band."},{"id":"recover-select","title":"Take the faulted unit out of the fleet","cue":"At the fleet console, take unit 14 out of the fleet before touching it."},{"id":"close-lane","title":"Close the lane","cue":"Carry the lane barrier to the lane mouth and set it."},{"id":"escort-push","title":"Push the unit to the bay","cue":"In manual mode, keep the push steady inside the band as the unit rolls to the service bay."},{"id":"find-cause","title":"Find the cause","cue":"Look along the shelf for what took the unit off its lane."},{"id":"hold-lane-closed","title":"Hold the lane closed","cue":"Hold the lane closure on the console while the unit is inspected."},{"id":"return-unit","title":"Return the unit to the fleet","cue":"Return unit 14 to the fleet once the cause is cleared and the scanner checks green."},{"id":"reopen","title":"Reopen the lane","cue":"Remove the barrier and reopen the lane on the console."},{"id":"find-blind-corner","title":"Walk the lane","cue":"Before you leave, find what makes this lane less safe than the plan says."},{"id":"closeout","title":"Log the drill and the recovery","cue":"Log the e-stop results, the fault cause and the missing mirror."}],"ad-cobot-risk-assessment-and-speed-separation":[{"id":"ppe","title":"Prepare for the bench","cue":"Safety glasses, safety shoes and long hair tied back before the bench."},{"id":"brief","title":"Open the risk assessment","cue":"Open the application's risk assessment and read the hazards it lists."},{"id":"walk-tasks","title":"Walk the application","cue":"Walk the operator's tasks, then check the gripper and the layout against the sheet."},{"id":"clean-scanner","title":"Check the area scanner","cue":"Check the area scanner's window is clean and unobstructed."},{"id":"zone-test","title":"Prove the zones with a body","cue":"Walk into the warning zone and watch the arm slow, then into the protective zone and watch it stop."},{"id":"stop-time","title":"Check the stopping performance","cue":"Read the stopping check and commit only in the green band the manual sets."},{"id":"stage-part","title":"Stage the part","cue":"Carry a part blank to the fixture tray."},{"id":"approach-walk","title":"Walk the approach","cue":"Keep your approach to the bench steady inside the band as the arm runs."},{"id":"find-gap","title":"Find the unassessed hazard","cue":"Look along the shelf for the hazard the sheet does not cover."},{"id":"force-hold","title":"Run the contact check","cue":"Hold the contact check through the test the manual describes."},{"id":"release-select","title":"Release the bench","cue":"With every control tested, release the bench for use."},{"id":"update-sheet","title":"Update the risk assessment","cue":"Add the sharp corner and its guard to the sheet."},{"id":"find-pendant","title":"Check the pendant","cue":"Before you leave, find the setting that should not be left as it is."},{"id":"closeout","title":"Sign the release","cue":"Sign the release log with the tests run and the sheet updated."}],"rp-construction-drilling-robot-setup":[{"id":"work-plan","title":"Read the work plan for the deck","cue":"Read the work plan: the bay, the anchor layout, the robot's zone and who runs it."},{"id":"deck-scan","title":"Read the deck scan","cue":"Read the scan of the slab for embedded conduit, tendons and rebar against the layout."},{"id":"ppe-deck","title":"Dress for overhead drilling","cue":"Hard hat, safety glasses and hearing protection."},{"id":"barricade","title":"Barricade the robot's reach","cue":"Carry the barricade stand to the corner mark so the tape encloses the robot's full reach."},{"id":"localise","title":"Check the robot's position on the control points","cue":"Check the robot's position against the control points and commit only when the readout is in the green."},{"id":"dust-shroud","title":"Connect the dust collection","cue":"Connect the drill's shroud to the vacuum dust collector and confirm it is running."},{"id":"find-conflict","title":"Find the hole you must not drill","cue":"Find the layout hole that lands on an embedded service in the scan."},{"id":"enable-hold","title":"Hold enable while it drives to hole one","cue":"Hold the controller's enable while the robot drives to the first position."},{"id":"drill-track","title":"Watch the vacuum flow through the first holes","cue":"Keep the dust collector's flow inside the band while the first holes are drilled."},{"id":"bit-change","title":"Change the bit the safe way","cue":"Stop the drill and lower the mast, isolate and lock the battery, then change the bit."},{"id":"hepa-clean","title":"Clean up with the HEPA vacuum","cue":"Clean the dust on the deck and the robot with the HEPA-filtered vacuum."},{"id":"handover","title":"Log the as-drilled holes","cue":"Log the holes drilled, the one removed for the conduit, and the bit changes for the foreperson."}],"ad-robot-cell-lockout-and-safe-reentry":[{"id":"ppe","title":"Suit up for the cell","cue":"Safety glasses, safety shoes and cut-resistant gloves before the gate."},{"id":"brief","title":"Read the lockout procedure","cue":"Confirm every energy source the cell's written procedure lists before touching anything."},{"id":"stop-cell","title":"Bring the cell to a normal stop","cue":"Use the cycle stop to end the program at a safe point."},{"id":"isolate","title":"Isolate and lock out","cue":"Open the disconnect, hang your own lock and tag, then dump the air."},{"id":"try-start","title":"Try the start","cue":"Press the cell start to prove it will not run."},{"id":"zero-energy","title":"Verify zero energy","cue":"Read the cell's energy check and commit only once it reads zero."},{"id":"block-axis","title":"Block the raised axis","cue":"Carry the block to the arm's rest point and seat it under the raised axis."},{"id":"jog-reduced","title":"Jog in reduced speed","cue":"With the pendant in reduced speed, keep the jog inside the band while the arm moves clear."},{"id":"find-damage","title":"Find the cause","cue":"Look along the shelf for what caused the jam."},{"id":"bleed-air","title":"Bleed the trapped air","cue":"Hold the bleed valve open until the line gauge falls to nothing."},{"id":"remove-block","title":"Remove the block","cue":"Take the axis block out once the work under the arm is done."},{"id":"clear-cell","title":"Clear the cell","cue":"Count everyone out and check the floor for tools before the lock comes off."},{"id":"find-open-gate","title":"Check the guarding","cue":"Before restart, find the guard that is not doing its job."},{"id":"closeout","title":"Remove your lock and log it","cue":"Remove your own lock, restore energy per the procedure and log the entry."}],"mooring-line":[{"id":"plan","title":"Read the mooring plan","cue":"Check the berth, the line plan — head, breast, spring — and which bollards take which lines."},{"id":"ppe","title":"Hi-vis, life vest, gloves and boots","cue":"Visible to the ship, buoyant if you go over the edge, hands and feet protected."},{"id":"zone","title":"Identify the snap-back zone","cue":"Read the painted zone at the bollard and stand outside it before the line comes."},{"id":"radio","title":"Establish comms with the ship","cue":"Radio check with the mooring officer: which line, which bollard, when to take up."},{"id":"heaving","title":"Take the heaving line","cue":"Let the monkey's fist land on the wharf, then pick up the heaving line and haul."},{"id":"haul","title":"Haul the mooring line ashore","cue":"Haul hand over hand, steady, keeping the line moving and your body out of the bight."},{"id":"eye","title":"Drop the eye on the bollard","cue":"Carry the eye to the bollard and drop it over — hands on the outside of the eye."},{"id":"tension","title":"Call the tension","cue":"Watch the line take up and call the ship to stop heaving inside the working tension."},{"id":"stopper","title":"Hold the stopper for the transfer","cue":"Hold the stopper on the line while the ship transfers it from winch drum to bitts."},{"id":"walk","title":"Walk the lines before all fast","cue":"Look at every line from bollard to fairlead and click the one that will not hold."}],"bunkering-watch":[{"id":"plan","title":"Read the bunker plan","cue":"Check the tanks, the quantity, the rate, the sequence and the ullages."},{"id":"doi","title":"Sign the declaration of inspection","cue":"Go through the DOI with the barge person in charge and both sign it."},{"id":"containment","title":"Contain the deck","cue":"Plug every scupper, set the drip tray under the manifold, and stage the SOPEP spill kit — before the hose comes aboard."},{"id":"hose","title":"Connect the hose","cue":"Land the hose flange on the manifold with a new gasket, fill every bolt hole, and blank the unused manifold connection."},{"id":"comms","title":"Prove comms and the emergency stop","cue":"Radio check with the barge on the agreed channel, and test the emergency stop signal end to end."},{"id":"lineup","title":"Line up tank-first","cue":"Open the receiving tank's filling valve first, then the manifold valve last."},{"id":"start","title":"Slow start and walk the deck","cue":"Signal the barge to start at minimum rate and hold it there while the hose, the flange and the deck are walked for leaks."},{"id":"sounding","title":"Take a sounding","cue":"Sound the receiving tank and commit when the reading matches the plan's expected level."},{"id":"topping","title":"Top off at reduced rate","cue":"At 85 percent, signal the barge to reduce, and commit at the topping-off rate."},{"id":"close","title":"Close the manifold","cue":"After the barge stops and blows the line, close the manifold valve."},{"id":"sample","title":"Seal the sample and sign the BDN","cue":"Take the continuous drip sample from the manifold cock, seal and label it with both signatures, then sign the bunker delivery note."},{"id":"walk","title":"Walk the deck before the hose comes off","cue":"Check every scupper, the tray and the flange, and click what is not as it was set."}],"crane-yard":[{"id":"pre-lift","title":"Read the lift plan","cue":"Confirm the load weight, working radius, boom angle and ground conditions."},{"id":"outrigger-setup","title":"Extend and set the outriggers","cue":"Extend the front and rear outriggers onto their pads."},{"id":"level-check","title":"Check the crane is level","cue":"Read the level bubble and commit only when it is centred."},{"id":"load-chart","title":"Verify the load chart for this pick","cue":"Walk the boom to the planned radius and commit once the chart shows capacity in hand."},{"id":"zone-teach","title":"Teach the anti-collision boundary","cue":"Walk the boom to each corner of the property line next door and mark it, in order, going around the corner."},{"id":"zone-save","title":"Save the boundary to the RCI","cue":"Commit the taught boundary to the crane's rated capacity indicator as a no-swing zone."},{"id":"zone-verify","title":"Test-swing and verify the cutout","cue":"Hold VERIFY while the RCI test-swings the boom and confirms it stops dead at the taught boundary."},{"id":"rigging-select","title":"Select the correctly rated sling","cue":"Choose the sling rated for this load from the rigging rack, not the damaged one beside it."},{"id":"inspect-shackle","title":"Inspect the shackle","cue":"Check the shackle's rated capacity stamp and pin condition before rigging it."},{"id":"sling-angle","title":"Measure the sling leg angle","cue":"Set the angle finder against a sling leg and commit once the reading is inside the rated range."},{"id":"signal-protocol","title":"Confirm the signal person protocol","cue":"Agree hand signals and radio call-outs with the dedicated signal person."},{"id":"hook-load","title":"Hook the rigging to the load","cue":"Attach the sling to the hook block and confirm the load is centred underneath it."},{"id":"tag-line-lift","title":"Guide the lift with the tag line","cue":"Keep a steady tension on the tag line as the load comes up and swings toward the landing zone."},{"id":"set-down","title":"Make a controlled set-down","cue":"Carry the load over the landing zone and lower it into place."},{"id":"log-lift","title":"Close out the lift log","cue":"Record the pick, confirm the area is clear, then boom down."}],"dock-crane":[{"id":"briefing","title":"Hold the pre-lift briefing","cue":"Confirm the container weight, lift plan and the lashing gang's positions."},{"id":"load-chart","title":"Check the load chart","cue":"Confirm the container's weight is inside the crane's rated capacity at this radius."},{"id":"wind-check","title":"Check wind speed against the rated limit","cue":"Read the anemometer and commit while it holds inside the crane's operating limit."},{"id":"red-zone-clear","title":"Confirm the red zone is clear","cue":"Check and flag the red zone beneath the lift path clear of the lashing gang."},{"id":"lashing-release","title":"Release the lashings top-down","cue":"Unwind and free the lashing rods from the top tier down to the bottom."},{"id":"spreader-position","title":"Position the spreader over the container","cue":"Land the spreader bar squarely on the container's corner castings."},{"id":"twist-lock-check","title":"Verify all four twist-locks","cue":"Check each corner by hand. Two of the four don't match what the panel shows."},{"id":"signal-check","title":"Confirm with the signal person","cue":"Get a clear signal from the deck before taking any weight on the hook."},{"id":"hoist","title":"Take the lift","cue":"Ease the hoist lever up and hold the take-up rate steady while the container comes clear of the stack."},{"id":"land-release","title":"Land and release in order","cue":"Lower fully onto the chassis, confirm the hook is slack, then release the locks and retract."},{"id":"agv-teach","title":"Teach the AGV route waypoints","cue":"Record the pickup, transit and stack points for the yard AGV, in that order."},{"id":"agv-save","title":"Save the AGV route","cue":"Commit the three waypoints to the yard's AGV coordination system."},{"id":"agv-run","title":"Dry-run the AGV route","cue":"Hold RUN/VERIFY and watch the route clear the swing radius and the gang before dispatch."},{"id":"log","title":"Close the lift log","cue":"Record the lift weight, wind reading and lock verification, and sign the plan closed."}],"cp-zero-emission-terminal-equipment-pre-use":[{"id":"read-operator-checklist","title":"Read each machine's posted checklist","cue":"Read the yard tractor's, the top pick's and the straddle carrier's posted checklists before walking to the first one."},{"id":"unplug-and-hang-cable","title":"Unplug the charge cable and hang it up","cue":"Unlatch the yard tractor's charge connector and carry the cable back to the dispenser's hanger."},{"id":"read-state-of-charge","title":"Read the state of charge against the shift","cue":"Read the tractor's state of charge and commit once it settles in the band the shift plan needs."},{"id":"find-hv-warning","title":"Read the dash for any warning","cue":"Switch on and read every warning on the tractor's dash before releasing the brake."},{"id":"tag-tractor","title":"Tag the tractor out and take the spare","cue":"Hang the do-not-operate tag on the tractor's wheel and key out; take the spare tractor on the board."},{"id":"cycle-twistlocks","title":"Cycle the top pick's twistlocks","cue":"Turn the twistlock switch through locked and unlocked and watch every indicator on the spreader follow."},{"id":"check-hydraulic-line","title":"Look along the spreader's hydraulic lines","cue":"Look along the hoses to the spreader for wet fittings, rubbing or bulges — look, never run a hand along them."},{"id":"walk-straddle-carrier","title":"Walk the straddle carrier","cue":"Frame and legs, then tyres and wheel nuts, then mirrors and cameras, in that order."},{"id":"find-broken-camera","title":"Check every camera image","cue":"Look at each camera's image on the cab screen and each camera housing on the legs."},{"id":"test-pedestrian-alert","title":"Test the pedestrian alert sound","cue":"Test the travel alarm and the pedestrian alert: you should hear both from the ground."},{"id":"hold-brake-test","title":"Hold the service brake test","cue":"On the test roll, apply the service brake and hold it until the machine is fully stopped and the regen gauge reads zero."},{"id":"write-up-defects","title":"Write up every defect","cue":"Write up the tractor's high-voltage warning, the carrier's cracked camera and anything else found, one line each."},{"id":"radio-foreman","title":"Tell the foreman which machines are ready","cue":"Radio the foreman: spare tractor out, top pick ready, carrier tagged for its camera."}],"cp-charging-yard-connectors-and-e-stops":[{"id":"read-switching-log","title":"Read the yard's switching log","cue":"Read which dispensers are tagged out, which breakers were switched overnight, and any faults the last shift wrote up."},{"id":"walk-dispenser-row","title":"Walk the dispenser row in order","cue":"Visit each dispenser from the entrance down: housing closed, screen alive, holster intact, signs readable."},{"id":"find-cracked-latch","title":"Look closely at each connector","cue":"Pick up each connector: pins straight and clean, seal intact, latch whole and springing back."},{"id":"tag-out-connector","title":"Tag the damaged connector out of service","cue":"Hang the out-of-service tag on dispenser 2 and holster the connector so nobody plugs it in."},{"id":"coil-trip-cable","title":"Get the cable off the drive lane","cue":"Carry the charging cable left across the drive lane back to its overhead hanger."},{"id":"test-yard-e-stop","title":"Test the yard emergency stop","cue":"Warn the yard on the radio, press the yard e-stop, confirm every dispenser screen goes dark."},{"id":"reset-e-stop-deliberately","title":"Reset the e-stop on purpose","cue":"Twist the e-stop to release it, then reset the yard controller — only once everyone is clear."},{"id":"plug-in-yard-tractor","title":"Plug in a yard tractor","cue":"Carry dispenser 1's connector to the parked tractor's inlet and seat it until the latch clicks."},{"id":"lock-out-breaker","title":"Lock out dispenser 2 at its breaker","cue":"Open dispenser 2's breaker in the yard switchgear and hang your lock and tag before the electrician opens the housing."},{"id":"watch-charge-session","title":"Watch the first minutes of the session","cue":"Stay at the dispenser and keep the session current inside the band until it settles."},{"id":"find-pooled-water","title":"Check the ground around the pedestals","cue":"Look at the base of each pedestal for pooled water, a cracked base or a damaged bollard."},{"id":"update-status-board","title":"Update the in-service board","cue":"Mark dispenser 2 out of service and dispenser 3 watched for drainage on the yard's status board."},{"id":"call-shift-lead","title":"Tell the shift lead","cue":"Radio the lead: connector latch cracked and locked out, cable hung, e-stop tested, puddle at dispenser 3 needs the drain cleared."}],"container-lashing":[{"id":"plan","title":"Read the bay plan and securing pattern","cue":"Check the tier heights, the weights and the rod pattern the Cargo Securing Manual calls for on this bay."},{"id":"crane-hold","title":"Hold the crane off the bay","cue":"Radio the crane: lashers entering the bay, hold all lifts until the all-clear."},{"id":"harness","title":"Harness on, clipped to the bridge line","cue":"Harness worn and the lanyard clipped before a foot goes on the lashing bridge."},{"id":"locks","title":"Prove every twist-lock","cue":"Check each twist-lock's handle is in the locked position — all four corners, every tier."},{"id":"rods","title":"Fit the lashing rods to the pattern","cue":"Hook the port rod into the casting, then the starboard rod, crossing as the pattern shows."},{"id":"seat","title":"Seat the rod in the casting","cue":"Hold the rod head in the corner casting until it drops fully home."},{"id":"turnbuckles","title":"Hand-tighten the turnbuckles","cue":"Take up the slack on each turnbuckle by hand, port then starboard, evenly."},{"id":"torque","title":"Set the turnbuckle tension","cue":"Tension each turnbuckle to the manual's figure and commit inside the band."},{"id":"lock-turnbuckle","title":"Lock the turnbuckles","cue":"Run the lock nut down against the body so the tension cannot back off."},{"id":"inspect","title":"Walk the bay before the all-clear","cue":"Check every lock and lashing on the way out and click what was missed."},{"id":"all-clear","title":"Give the crane the all-clear","cue":"Radio the crane: lashers out of the bay, lifts may resume."}],"shore-power-hookup":[{"id":"plan","title":"Check compatibility and the berth rating against the plan","cue":"Confirm the vessel's shore-power system and the berth's rated capacity match the connection plan."},{"id":"stage","title":"Stage PPE for the connection","cue":"Rated gloves, arc-rated coveralls and the insulating mat down before a connector is touched."},{"id":"cms-position","title":"Position the cable management system at the vessel's connection point","cue":"Wheel the CMS into place under the ship's shore-power receptacle and drop it on the mark."},{"id":"reel-payout","title":"Pay out the cable reel with the crane","cue":"Signal the crane to lower the reel's load steadily — never let the cable go slack on the quay or snatch tight."},{"id":"connectors","title":"Land the connectors, ground first","cue":"Land the ground connector into the shore connection box, then the two phase connector banks."},{"id":"interlock","title":"Prove the interlock and the pilot circuit","cue":"Engage the mechanical interlock and prove continuity on the pilot circuit before anything is energised."},{"id":"insulation-test","title":"Test insulation resistance before energising","cue":"Run the megger on the made-up cable and commit the reading against the minimum."},{"id":"breaker-permission","title":"Call the port for the order to close the shore breaker","cue":"Radio the port's control room: connection made, interlock proven, ready to energise."},{"id":"breaker-close","title":"Close the shore-side breaker","cue":"Turn the shore breaker's handle through to closed, on the port's order."},{"id":"sync-check","title":"Confirm synchronisation with the ship's electrician","cue":"Hold the sync check while the ship's electrician confirms voltage, frequency and phase rotation match."},{"id":"vessel-breaker","title":"Have the vessel breaker closed","cue":"Confirm with the ship's electrician that the vessel's shore breaker is closed and load is transferring."},{"id":"shutdown-observe","title":"Watch the auxiliary engines shut down","cue":"Confirm both auxiliary engines have shut down now that shore power is carrying the ship's load."},{"id":"walk","title":"Walk the connection before signing off","cue":"Check every connector, the interlock and the strain relief before logging the hookup complete."}],"me-water-column-sampling-from-a-small-boat":[{"id":"sampling-plan","title":"Read the sampling plan for this station","cue":"Check the station's position, the marks on the line the plan calls for, the bottles and preservatives per parameter, the holding conditions, and the custody chain to the laboratory."},{"id":"deck-kit","title":"Vest, clean gloves and an iced cooler before the gate opens","cue":"Work vest zipped before the rail gate is touched, a fresh pair of nitrile gloves from the box, and the cooler iced with its lid ready."},{"id":"disk-read","title":"Lower the disk and commit the reading where it vanishes","cue":"Lower the disk on the shaded side until it disappears, raise it until it just reappears, and commit the mark between the two."},{"id":"clip-bottle","title":"Clip the sampling bottle to the line, open and cocked","cue":"Open both ends of the sampling bottle, cock the trip, and clip it to the line's snap above the weight."},{"id":"lower-to-mark","title":"Wind the bottle down to the plan's mark on the line","cue":"Pay the line out on the winch until the plan's coloured mark is at the block — no further, no less."},{"id":"trip-hold","title":"Hold the line still and send the messenger","cue":"Hold the line steady at the mark with the winch locked, drop the messenger, and keep the line still for the full count until you feel the trip."},{"id":"retrieve-steady","title":"Bring the bottle up steady on the winch","cue":"Wind the bottle up at a steady rate, watching the line and the block, and stop with the bottle at the gate rather than at the block."},{"id":"inspect-cast","title":"Inspect the cast and the bottles before decanting","cue":"Look over the sampling bottle's seals and the empty sample bottles' labels before a drop of water is poured."},{"id":"rinse-fill-label","title":"Rinse, fill and label each sample bottle in order","cue":"For each unpreserved bottle: rinse it three times with a little of the cast, fill it to the shoulder and cap it, then complete its label — preserved bottles are filled without the rinse, as the plan says."},{"id":"blank-read","title":"Read the cooler's temperature blank against the plan's band","cue":"Read the temperature blank riding in the cooler's ice and commit it against the holding band the plan gives."},{"id":"rack-cooler","title":"Seal the cooler and rack it under custody","cue":"Sign the custody form, seal it in its bag on the lid, put the custody tape across the lid, and rack the cooler in the wheelhouse rack."},{"id":"skipper-checkin","title":"Check in with the skipper before leaving station","cue":"On the radio: the station is sampled, racked and logged, the gate is shut, and how the deck is after the wake and the fouled line."},{"id":"station-log","title":"Write the station log and close the custody form","cue":"Log the station, the disk reading, the marks sampled, bottles filled by parameter, the split seal and the repeated cast, the blank, the wake and the fouled line, and the cooler's custody number."}],"me-fish-visual-census-and-data-sheet":[{"id":"census-plan","title":"Read the census plan against the dive plan","cue":"Check the belt's number and its corridor width, the method's swim time and pace, the size classes, the rule for what counts, and the dive plan's limits as briefed."},{"id":"census-kit","title":"Check the slate, the bar and the timer","cue":"Slate ruled with the sheet's columns and its pencil on, the size bar on its lanyard, and the timer running and readable."},{"id":"vis-check","title":"Commit the visibility against the method's minimum","cue":"Look along the belt to the visibility target and commit whether it can be read at the method's distance — the plan's minimum, not your opinion."},{"id":"bar-check","title":"Check the size bar against its calibration target","cue":"Hold the size bar against the painted calibration marks on the start stake and confirm the classes line up before the swim."},{"id":"set-timer","title":"Set the timer bezel for the method's swim time","cue":"Turn the bezel so the swim time the method gives reads from the timer's hand at the start marker."},{"id":"census-swim","title":"Swim the belt at the method's pace, counting ahead","cue":"Swim the belt at the pace the timer sets, eyes ahead across the corridor, counting and classing what enters it — never behind, never off the line."},{"id":"timer-read","title":"Read the timer at the end marker and commit the swim time","cue":"At the end marker, read the timer against the bezel and commit whether the swim came in inside the method's band."},{"id":"find-end","title":"Find the end marker and note the plume on the corridor","cue":"Pick out the belt's end stake and the silt plume that crossed the last stretch; the first ends the count, the second goes on the sheet."},{"id":"tail-count","title":"Hold at the end marker for the tail count","cue":"Hold still at the end stake for the method's tail count, eyes on the corridor ahead, counting what crosses in the settle time."},{"id":"write-sheet","title":"Write the data sheet column by column","cue":"Total the tally marks into the count column, confirm each line's size class against the bar, then fill the remarks — swim time, visibility, the plume, your initials and the time."},{"id":"bag-slate","title":"Bag the slate on the downline clip","cue":"Clip the slate into the survey bag on the downline's travelling clip so it goes up with the stage, not in your hand."},{"id":"buddy-checkin","title":"Check in with your buddy before the ascent","cue":"Face your buddy at the downline: exchange the okay, confirm the recall was acknowledged, and agree the ascent on the plan."},{"id":"census-log","title":"Log the census and the dive on the boat","cue":"On the boat's log: belt number, swim time, visibility and the plume, counts per class transcribed from the slate, the recall and the ascent, and the dive record's own entries."}],"me-invasive-species-identification-and-reporting":[{"id":"reporting-protocol","title":"Read the reporting protocol for a sighting","cue":"Check the reference card this survey works from, what a mismatch triggers, the photo set the protocol wants, the position accuracy, what sampling the permit allows, who is called, and what is not done."},{"id":"sighting-kit","title":"Check the camera, the scale card and the position unit","cue":"Camera charged with the pole and the mirror attached, the scale and colour card in the kit, and the position unit on and settling before the first photograph."},{"id":"walk-the-float","title":"Walk the float's edge at survey pace, checking the underside","cue":"Walk the float's edge on a knee's width inboard at the protocol's pace, checking the underside with the mirror at each cleat — steady, both hands free of the water."},{"id":"fix-position","title":"Fix the position to the protocol's accuracy","cue":"Hold the position unit over the cleat nearest the patch and commit the fix when its accuracy reading is inside the protocol's band."},{"id":"set-scale","title":"Set the scale card beside the specimen","cue":"Set the scale and colour card flat on the float beside the patch, in the same plane as it, without touching the patch."},{"id":"camera-hold","title":"Hold the camera steady for the diagnostic close-up","cue":"Hold the camera square over the patch and the card at the protocol's distance for the full count — no tilt, no shadow, no hurry."},{"id":"photo-set","title":"Take the protocol's photo set in order","cue":"Overall shot of the patch where it sits, then the close-up with the card, then the habitat shot showing the float, the cleat number and the water — in that order, every time."},{"id":"find-more","title":"Find the earlier tag and the second patch","cue":"Before the sample, look for a report tag from an earlier crew and for any other patch on this float's edge; both change what goes on the form."},{"id":"bag-sample","title":"Take the permitted sample and seal the jar","cue":"Take only what the permit's line on the protocol allows, with the forceps, into the labelled jar of site water, and turn the lid down until the seal indicator lines up."},{"id":"report-form","title":"Complete the sighting report form","cue":"Fill the position box with the marina, float, cleat and the committed fix; the photo box with the frame numbers per shot and the earlier tag; and the contact box with observer, crew, time and who was called."},{"id":"coordinator-call","title":"Call the coordinator and read the form","cue":"On the radio: read the form to the coordinator — position, what was seen, the photo set, the tag, the sample taken as permitted — and take their instruction on the float before leaving it."},{"id":"sighting-log","title":"Log the sighting in the survey record","cue":"Log the float and cleat, the fix, the photo frames, the tag, the second patch, the sample and its destination, the coordinator's instruction, and the boater's request and the answer given."}],"mw-pier-pile-inspection-dive":[{"id":"on-bottom","title":"Report on the bottom to the supervisor","cue":"Call the supervisor: on the bottom, off the stage, feeling good, visibility and current as you find them, starting on the first pile."},{"id":"umbilical-check","title":"Check your umbilical hand over hand to the harness","cue":"Run a hand down the umbilical from the helmet to the harness: strain relief clipped to the harness ring, no turns round the stage bridle, slack enough to reach the work and no more."},{"id":"scraper-down","title":"Take the scraper off the stage to the pile","cue":"Unclip the scraper from the stage rail on its lanyard and bring it to the band on the first pile."},{"id":"pile-one","title":"Inspect the first pile at the band and the mudline","cue":"Look along the scraped band and down to the mudline: cracks, spalls, exposed rebar, rust staining, and any loss of section where the pile meets the silt."},{"id":"pneumo-depth","title":"Hold the pneumo at the defect and let the supervisor read it","cue":"Hold the pneumo hose's end at the spall while the supervisor bleeds it, and commit the reading against the depth the dive plan gives for this bent."},{"id":"clear-faceplate","title":"Crack the free-flow to clear the faceplate","cue":"Open the helmet's free-flow valve a part turn to clear the fogging off the faceplate for the close look, then close it back."},{"id":"measure-section","title":"Measure the remaining section with the caliper","cue":"Set the caliper across the pile at the mudline necking and read the measurement up to the supervisor for the record."},{"id":"clean-band","title":"Clean the second pile's band at a pace your supply holds","cue":"Scrape the band on the second pile steadily, pacing your breathing so the supervisor sees you steady on the supply — not racing the growth."},{"id":"pile-two","title":"Inspect the second pile's jacket and its anode lead","cue":"Look along the jacket for splits and washed-out grout, and follow the cathodic protection lead from the pile to its anode on the silt."},{"id":"photograph","title":"Photograph each defect against a scale","cue":"Place the scale bar flat against the spall first, then take the photograph square to it with the strobe."},{"id":"tools-up","title":"Send the tools back up on the stage","cue":"Clip the tool bag back onto the stage rail so it goes up with you, nothing left on the bottom."},{"id":"findings-up","title":"Read your findings up for the dive log","cue":"Read your slate to the supervisor: pile, depth, the spall and the rebar, the section measured, the jacket split and the broken anode lead, the loose timber."},{"id":"leave-bottom","title":"Check in and leave the bottom on the supervisor's call","cue":"Tell the supervisor you are on the stage and ready to leave the bottom, how you feel after the band and the current, and wait for the call."}],"mw-underwater-welding-and-cutting":[{"id":"switch-plan","title":"Agree the job and the switch plan on the comms","cue":"With the supervisor and the tender at the switch: the cut and the patch, the procedure qualified to AWS D3.6, and the switch stays cold until you call 'make it hot' — and goes cold on 'make it cold' or on silence."},{"id":"umbilical-check","title":"Check the umbilical and leads to the harness","cue":"Run your hand from the helmet down the umbilical to the harness ring, and along the welding lead and ground lead where they run with it: clipped, no turns round the stage, nothing crossing the work."},{"id":"torch-down","title":"Take the cutting torch off the stage to the work","cue":"Unclip the oxy-arc torch from the stage rail, keep its tip pointed away from you, and hang it on the work hook beside the cut line."},{"id":"pre-burn-check","title":"Check the work for a sealed void and the ground spot","cue":"Before any arc: is there a closed space behind the cut where gas can collect, and is the ground spot bare, clean steel close to the work?"},{"id":"ground-and-switch","title":"Ground on clean steel first, then call for the switch","cue":"Put the ground clamp on the cleaned spot close to the cut, facing you across the work, then call 'make it hot' and wait to hear 'hot' back from the tender."},{"id":"burn-depth","title":"Hold the pneumo at the cut for the supervisor","cue":"Hold the pneumo end at the cut line while the supervisor bleeds and reads it, and commit the reading against the depth range the dive plan and the qualified procedure give."},{"id":"run-cut","title":"Run the cut at a steady oxygen flow","cue":"Hold the torch on the cut line and keep the oxygen flow steady on the trigger as you travel — enough to blow the cut through, never gulping or starving it."},{"id":"make-it-cold","title":"Call 'make it cold' before the rod change","cue":"Take the torch off the work, call 'make it cold', and wait to hear 'cold' back from the tender before touching the rod."},{"id":"oxygen-off","title":"Close the torch's oxygen valve","cue":"With the switch cold, close the oxygen valve on the torch fully before the rod comes out and the torch goes back on its hook."},{"id":"seat-patch","title":"Seat the patch plate over the cut","cue":"Guide the patch plate down off its lift bag onto the cut-back opening, square to the marks, dumping the bag's air as the plate takes its seat."},{"id":"weld-pass","title":"Run the weld pass on the patch","cue":"Ground checked, rod on the work, call 'make it hot', hear 'hot', and run the pass along the patch's edge at a steady drag — then 'make it cold'."},{"id":"weld-inspect","title":"Inspect the weld against the procedure","cue":"Look along the pass with the switch cold: undercut at the toes, porosity, cracks, and the profile against what the procedure accepts."},{"id":"dive-log-weld","title":"Read the job up for the dive log","cue":"Read your slate to the supervisor: the cut and the patch, the depth, the rods used, the sealed void and how it was vented, the lost comms and the current, and the defects to be ground out."},{"id":"crew-checkin","title":"Check in with the supervisor and the tender","cue":"Switch confirmed cold, torch and stinger on the stage, and on the comms: how you are after the dead comms mid-cut and the current on the pass, and ready for the supervisor's call up."}],"gg-pile-driver-fender-repair":[{"id":"lift-plan","title":"Read the lift plan and the fender drawing","cue":"Read the lift plan: the panel's weight, the davit's rating at this reach, the rigging, the barge's position below, the boat exclusion on the water, and the signal person."},{"id":"rail-ppe","title":"Vest on and clipped to the rail anchor","cue":"Put on the flotation vest and zip it, and clip your lanyard to the rated anchor at the railing, before anyone goes to the edge."},{"id":"old-wale","title":"Read the removed wale for what failed","cue":"Look over the old wale the barge crew sent up and find why it failed: borers, splits, wasted bolts."},{"id":"wind","title":"Take the wind before the lift","cue":"Read the anemometer at the davit and commit the reading while it sits inside the band below the lift plan's limit."},{"id":"through-bolts","title":"Torque the new panel's through-bolts","cue":"Run the through-bolts up on the new panel in the drawing's order, washers square to the timber, to the figure on the drawing."},{"id":"shackle","title":"Shackle the sling to the panel's lifting eyes","cue":"Carry the sling's shackle to the lifting eye on the panel, pin it and mouse the pin."},{"id":"test-lift","title":"Make the test lift and hold it","cue":"Take up the slack and lift the panel a few centimetres off the cribbing, and hold it there while the rigging and the davit are checked."},{"id":"lower","title":"Lower the panel over the rail on the tag line","cue":"With the davit lowering steadily, keep the panel from spinning on the tag line — firm, not fighting it — as it goes over the rail and down to the barge."},{"id":"hand-over","title":"Hand the lift to the barge's signal person","cue":"As the panel reaches the barge crew's reach, hand the signals to the barge's signal person and let go of the tag line on their word."},{"id":"recover","title":"Slack on the barge's signal, then bring the hook up latched","cue":"Slack the hoist line only when the barge's signal person calls it, then bring the empty hook up with its safety latch closed."},{"id":"deck-check","title":"Check the deck and the rigging after the lift","cue":"Walk the rail and the rigging after the lift and find what the lift left behind."},{"id":"fender-log","title":"Log the lift and the old wale's findings","cue":"Record the panel lowered and its position on the drawing, the wind, the old wale's borers, split and wasted bolt, and the sling taken out of service."},{"id":"crew-checkin","title":"Check in with the barge crew and the davit operator","cue":"Call the barge crew and the operator: panel down, hook up, lift logged — and how everyone is after a lift over the side in the fog."}],"cd-pier-piling-inspection-and-wrap-repair":[{"id":"pile-brief","title":"Read the inspection plan on the slate","cue":"At the pile, read your slate: which pile this is, where the inspection band is marked, what the form wants recorded and what the surface will say when the band is done."},{"id":"clear-growth","title":"Clear the growth from the inspection band with the scraper","cue":"Scrape the growth off the marked band round the pile in steady strokes — firm enough to take the growth, never so hard the scraper gouges the pile's face."},{"id":"tactile-inspect","title":"Read the cleared band by hand","cue":"With both gloved hands, feel round the whole band: the pile's diameter against the one above, any softness, splits, exposed steel or hollow sound when tapped."},{"id":"video-pass","title":"Hold the camera on the band while the surface records","cue":"Bring the helmet camera onto the cleared band and hold it steady, working slowly round the pile, while the supervisor confirms the picture and records."},{"id":"measure-band","title":"Gauge the section loss against the inspection form","cue":"Set the pit gauge across the necked section and commit when the reading sits in the class the form describes for this pile — not more, not less."},{"id":"dictate-findings","title":"Dictate the findings to the surface log","cue":"On comms, pile by pile as the form wants it: the pile number, the band cleared, the necked section and its class, the split and where it runs, and that the video is taken."},{"id":"prep-wrap-zone","title":"Brush the wrap zone to bare surface, then flush it","cue":"Wire-brush the whole wrap zone above and below the defect to a clean surface, then flush it with the water jet, pointed at the pile only."},{"id":"fit-jacket","title":"Fit the jacket halves round the wrap zone","cue":"Bring the first jacket half to the pile with its seam on the marked line, hold it while the surface passes the second, and close them round the pile."},{"id":"fasten-bands","title":"Tighten the bands round the jacket","cue":"Tension the banding round the jacket top and bottom with the tool until the jacket sits firm on its standoffs and the bands do not slip."},{"id":"seal-seam","title":"Check the jacket seam and the bottom seal by hand","cue":"Run a gloved hand down both seams and round the bottom seal: closed, no gap, no hose or growth caught in them."},{"id":"land-grout-hose","title":"Land the grout hose in the top port","cue":"Bring the grout hose to the jacket's top port, seat it and tell the surface 'hose landed — ready for grout' before anyone starts the pump."},{"id":"photo-plate","title":"Photograph the finished wrap with its identity plate","cue":"Hold the pile's identity plate against the jacket and let the surface take the still from the helmet camera: pile number, jacket, date plate and the grout port capped."},{"id":"surface-log","title":"Close the surface log for this pile","cue":"Before you leave the pile, read the log back with the supervisor: the findings, the class, the wrap fitted, the bands, the grout and the photograph, and the fender and the recall."},{"id":"crew-checkin","title":"Check in with the dive team at the stage","cue":"Back at the stage: the pile's findings said once more for the team, the fender to be lashed before the next pile, the craft that came in, and how everyone is doing."}],"cd-underwater-wet-welding-and-cutting":[{"id":"weld-brief","title":"Take the AWS D3.6 job briefing at the comms panel","cue":"At the supervisor's panel, in your PFD and dry gloves: the qualified welding procedure card, who owns the knife switch, the exact words for 'make it hot' and 'make it cold', and what happens if comms go."},{"id":"check-leads","title":"Walk the leads from the machine to the water's edge","cue":"Run your hand and your eyes along the welding lead and the ground lead from the machine terminals to the apron edge: jacket, connectors, lugs and the strain on each."},{"id":"set-ground","title":"Clamp the ground on bright steel on the work","cue":"Take the ground clamp to the pile's steel jacket at the point the procedure card marks, on metal the diver has already cleaned to bright, and close it hard."},{"id":"polarity-check","title":"Confirm the output is off, then read the polarity against the card","cue":"At the machine, confirm the output contactor is open and the knife switch is open, then read the lead polarity at the terminals against the procedure card."},{"id":"set-output","title":"Set the machine's output to the procedure card","cue":"Turn the output control to the setting on the procedure card for this electrode and this position, and leave it there."},{"id":"diver-insulation","title":"Check the diver-welder's gloves and helmet insulation","cue":"At the stage: the diver's rubber gloves whole and over the cuffs, the helmet's insulating fittings in place, no bare metal where the electrode holder rests."},{"id":"switch-hold","title":"Hold the knife switch open until the diver calls for it","cue":"Gloves on, hand on the handle, switch open. Listen to the comms: the diver is positioning the electrode against the work and will call 'make it hot' when ready."},{"id":"make-hot","title":"Close the switch on 'make it hot'","cue":"The diver calls 'make it hot'. Repeat the call back on the comms, then close the knife switch in one movement."},{"id":"weld-track","title":"Tend the welding lead while the diver runs the bead","cue":"Keep the welding lead in hand over the roller with just enough slack for the diver to move along the bead — no strain on the electrode holder, no belly of lead in the water."},{"id":"make-cold","title":"Open the switch on 'make it cold'","cue":"The rod is spent and the diver calls 'make it cold'. Repeat it back, open the knife switch, and tell the diver 'switch is cold' before they touch the holder."},{"id":"change-electrode","title":"Bag the spent stub, then send down a fresh rod","cue":"Haul the stub bag up the electrode line, drop the spent stub in the bag, then load a fresh electrode from the sealed quiver and send it down."},{"id":"read-bead","title":"Read the bead on the diver's video against the card","cue":"Watch the helmet camera as the diver brushes the bead and commit when the profile, the toes and the start and stop read as the procedure card's visual acceptance describes."},{"id":"weld-record","title":"Write the weld record and the dive log entry","cue":"At the record table: the procedure card number, the electrodes used and the stubs bagged, the machine setting, every hot and cold call with its time, the lead fault found and the deckhand on the stage."},{"id":"crew-checkin","title":"Check in with the dive team","cue":"At the team board: the diver-welder's condition and who is watching them, the lead tagged out for repair, the deckhand and the stage, the garbled comms, and how everyone is."}],"br-surface-supplied-dive-station-setup":[{"id":"take-setup","title":"Take the station setup from the supervisor","cue":"At the log table, in your PFD: the diving mode for today, the station layout from the employer's safe practices manual, the primary and secondary supplies the dive plan names, and who sets up what."},{"id":"run-intake","title":"Run the compressor's intake upwind of every exhaust","cue":"Carry the compressor's intake hose to the upwind rail, clear of the generator's stack and the crew boat's outboards, and clip it high."},{"id":"inspect-compressor","title":"Inspect the compressor and its filtration before it runs","cue":"Walk the compressor with it stopped: the filter tower and its cartridge tag, the belt and its guard, the oil, the hoses and the pressure relief."},{"id":"drain-tank","title":"Blow the condensate out of the volume tank","cue":"Open the volume tank's drain valve and let the water and oil blow out until the air runs dry, then close it."},{"id":"line-up-supplies","title":"Make up the primary supply, then line up the secondary","cue":"Connect the primary supply hose from the volume tank to the panel's primary inlet, then line up the high-pressure bank to the secondary inlet with the whip check clipped."},{"id":"read-bailout","title":"Read the bailout bottle against the dive plan","cue":"Crack the bailout bottle's valve, let the gauge settle and commit the reading against the charge the dive plan sets for this depth."},{"id":"nrv-test","title":"Prove the helmet's non-return valve","cue":"With the helmet's gas inlet disconnected, hold the test: try to draw back through the non-return valve and keep trying until it has held — nothing should come back."},{"id":"umbilical-ends","title":"Check the umbilical's pneumo and comms ends","cue":"At the helmet end of the umbilical: blow through the pneumo hose and look at the comms connector's pins before anything is made up to the helmet."},{"id":"bring-up-panel","title":"Bring the panel up to the dive plan's supply and hold it","cue":"Open the panel regulator steadily to bring the diver's supply up to the over-bottom pressure the dive plan sets, and hold it there while the supervisor watches the gauges — no overshoot, no hunting."},{"id":"zero-pneumo","title":"Zero the pneumo with the hose end at the surface","cue":"With the pneumo hose's end held at the waterline, bleed it and set the pneumofathometer to read zero at the surface."},{"id":"stage-standby","title":"Stage the standby diver's helmet on the bench","cue":"Carry the standby's helmet to the bench beside their umbilical, made up and ready to go on in a hurry."},{"id":"setup-log","title":"Log the station setup","cue":"Record the compressor inspection and the filter changed, the tank blown down, both supplies lined up, the bailout charged, the non-return valve proven, the pneumo cleaned and zeroed and the comms connector changed."},{"id":"crew-checkin","title":"Report the station ready and check in with the team","cue":"Tell the supervisor the station is set and logged, walk the tender and the standby through what changed, and check how everyone is before the diver dresses."}],"chlorine-room":[{"id":"sop","title":"Read the SOP and today's feed rate","cue":"Check the change-out procedure, the feed setpoint and who is the outside operator."},{"id":"monitor","title":"Check the room monitor","cue":"Read the chlorine monitor and bump-test it — commit when it reads inside the clean-air band."},{"id":"scba","title":"Stage the SCBA and post the outside operator","cue":"SCBA checked and staged at the door; a second operator outside the room with a radio and eyes on the window."},{"id":"close","title":"Close the empty cylinder's valve","cue":"Turn the valve on the empty cylinder fully closed with the cylinder wrench."},{"id":"capoff","title":"Remove the regulator, cap and hood the empty","cue":"Vacuum regulator off the valve, outlet cap on, protective hood over the valve — in that order."},{"id":"swap","title":"Bring the full cylinder onto the scale","cue":"Roll the full cylinder from the storage rack, hooded, and seat it on the scale."},{"id":"secure","title":"Chain the cylinder and fit a new gasket","cue":"Chain the cylinder upright to the wall bracket, and take a new lead gasket from the sealed pack for the yoke."},{"id":"yoke","title":"Tighten the yoke","cue":"Snug the yoke by hand, then a quarter turn with the wrench — commit inside the band."},{"id":"leaktest","title":"Ammonia leak test every joint","cue":"Hold the ammonia bottle's vapour under the yoke, the regulator and the valve packing — a white cloud is a leak."},{"id":"open","title":"Open the valve one turn","cue":"Open the new cylinder's valve one full turn — no more — and leave the wrench on the stem."},{"id":"feed","title":"Set the feed rate","cue":"Adjust the rotameter to the SOP setpoint and commit inside the band."},{"id":"walk","title":"Walk the room before leaving","cue":"Check the in-service cylinder, the kit and the door, and click what is not as it should be."}],"ut-water-treatment-chemical-delivery-unloading":[{"id":"read-manifest","title":"Read the delivery manifest","cue":"Check the manifest: the chemical, the quantity, and that this is today's ordered delivery."},{"id":"check-sds","title":"Review the safety data sheet","cue":"Check the SDS for this exact chemical before anything connects."},{"id":"verify-placards","title":"Verify the placard against the tank label","cue":"Find and compare the tanker's placard and the storage tank's own label."},{"id":"spill-kit-staged","title":"Stage the spill kit before the transfer","cue":"Confirm the spill kit and containment are staged at the connection point before anything flows."},{"id":"ppe-and-ground","title":"Don PPE and ground the tanker","cue":"Put on the PPE this chemical's SDS calls for, then ground the tanker to the plant's lug."},{"id":"connect-fill-hose","title":"Connect the fill hose to the correct tank","cue":"Carry the fill hose to the tank this delivery's manifest actually names."},{"id":"check-tank-capacity","title":"Check the tank's available capacity","cue":"Bring the level reading up to where the tank actually sits, then commit."},{"id":"open-transfer-valve","title":"Open the transfer valve slowly","cue":"Wind the transfer valve open slowly, watching the coupling as flow begins."},{"id":"watch-connection-start","title":"Watch the coupling as flow begins","cue":"Hold your attention on the coupling for the full watch as the transfer gets going."},{"id":"watch-tank-level","title":"Watch the tank level through the transfer","cue":"Watch the level rise and stay under the high-level band for the whole transfer."},{"id":"leak-inspection-walk","title":"Walk the hose run mid-transfer","cue":"Walk the full length of the hose and find what the watch at the tank end cannot see."},{"id":"close-transfer-valve","title":"Close the transfer valve slowly","cue":"Wind the valve shut slowly once the delivery is complete."},{"id":"disconnect-and-cap","title":"Drain and cap the hose","cue":"Drain the hose's residual chemical to containment, then cap both ends."},{"id":"complete-log","title":"Complete the delivery log","cue":"Log the quantity received, the tank's level after the delivery, and the chemical's lot number."}],"lift-station":[{"id":"workorder","title":"Read the work order and the well data","cue":"Check which pump, the wet-well depth, the last gas readings and the bypass plan."},{"id":"gas","title":"Test the wet-well atmosphere through the vent","cue":"Drop the meter probe through the vent port — oxygen, then flammable, then H2S — before the hatch moves."},{"id":"lockout","title":"Lock out the duty pump","cue":"Open the pump's disconnect at the control panel and hang your lock."},{"id":"bypass","title":"Set up bypass pumping","cue":"Suction into the wet well, discharge to the downstream manhole, then start the bypass pump."},{"id":"bypass-level","title":"Confirm the bypass is holding the level","cue":"Watch the well level and commit once the bypass holds it steady below the pump-on set point."},{"id":"hatch","title":"Open the hatch and set the guard","cue":"Open the wet-well hatch and drop the safety grate across the opening."},{"id":"lift","title":"Lift the pump on the guide rail","cue":"Hold the hoist up until the pump clears the hatch and swings to the pad."},{"id":"set-down","title":"Land the pump on the pad","cue":"Swing the pump over and set it down on the wash-down pad before anyone handles it."},{"id":"inspect","title":"Find the fault on the pad","cue":"Inspect the pump and click the fault."},{"id":"restart","title":"Rail the pump back, close the hatch, remove the lock, restart","cue":"Pump back on the rail, hatch closed, your lock off, bypass off, duty pump to auto."}],"ib-pressure-vessel-confined-entry-and-hot-work":[{"id":"permit","title":"Read the confined-space and hot-work permits together","cue":"Confirm the vessel, the isolation points and the hot-work conditions named on both permits."},{"id":"atmosphere-test","title":"Test the vessel atmosphere","cue":"Sample the vessel interior and commit only inside the safe oxygen range."},{"id":"isolate-vessel","title":"Isolate the vessel to zero energy","cue":"Blank the inlet, blank the outlet, then open the bleed valve to prove zero pressure."},{"id":"combustibles-clear","title":"Clear combustibles from the work area","cue":"Three things in this vessel will burn if the weld throws a spark their way. Find them before hot work starts."},{"id":"fire-watch-post","title":"Post the fire watch","cue":"Station the fire watch at the manway with an extinguisher before hot work begins."},{"id":"entry-sequence","title":"Enter through the manway","cue":"Don the harness, clip the retrieval line, then go through the manway."},{"id":"grind-prep","title":"Grind and prep the patch area","cue":"Grind the patch area to bright metal and hold the pass steady until it is fully prepped."},{"id":"weld-patch","title":"Run the patch weld","cue":"Hold the torch travel speed steady across the patch."},{"id":"recheck-atmosphere","title":"Recheck the atmosphere mid-job","cue":"Sample the atmosphere again and commit only inside the safe range."},{"id":"weld-inspect","title":"Visually inspect the finished patch","cue":"Check the weld bead with the inspection mirror for undercut, porosity or missed spots."},{"id":"exit-sequence","title":"Exit and confirm headcount","cue":"Unclip the retrieval line, exit through the manway, then confirm the headcount with the attendant."},{"id":"final-walk","title":"Walk the vessel before closing the manway","cue":"Three things inside this vessel should not be there. Find them before anyone closes the manway."},{"id":"crew-checkin","title":"Check in with the entry supervisor","cue":"Report the atmosphere readings, the fire watch's post-work observation period, and how the entry felt."},{"id":"closing-log","title":"Sign the entry and hot-work closeout log","cue":"Record the atmosphere readings, the weld inspection result and the headcount, then sign."}],"confined-rescue":[{"id":"sizeup","title":"Size up the space","cue":"Read the permit board: what the space is, what is in it, how far down the patient is."},{"id":"refuse","title":"Hold the crew at the hole","cue":"Physically hold back the coworker who is climbing in after their partner."},{"id":"isolate","title":"Isolate the space","cue":"Close the feed valve, lock and tag it, then set the blank flange."},{"id":"vent","title":"Aim and start the ventilation","cue":"Turn the blower to point its intake into clean air, upwind, with the duct running to the bottom of the space."},{"id":"monitor","title":"Monitor top, middle and bottom","cue":"Lower the meter through the space and commit when the readings are inside the entry band."},{"id":"rig","title":"Rig the system","cue":"Set the tripod over the opening with the legs chained, reeve the main line and mechanical advantage, then the belay on its own anchor."},{"id":"air","title":"Prepare the entrant","cue":"Entrant on supplied air with an escape bottle, attendant at the opening with the log, comms tested."},{"id":"entrant-descend","title":"Lower the entrant","cue":"Lower on the main line at a steady, controlled rate with the belay tracking."},{"id":"package","title":"Package the patient","cue":"Airway first with supplied air, then the rescue harness, then clip to the main line."},{"id":"haul","title":"Haul the patient out","cue":"Haul on the mechanical advantage at a steady rate while the belay is minded."},{"id":"handover","title":"Hand over and secure","cue":"Patient to EMS with what they were breathing, the atmosphere log to the incident commander, and the space tagged closed."}],"uw-intake-screen-cleaning-with-lockout":[{"id":"identify-energy-sources","title":"Find every energy source before touching anything","cue":"At the platform panel, before any switch is thrown: find the pump motor's breaker and the separate rake drive that can move the screen on its own timer."},{"id":"apply-lock-tag","title":"Rack the breaker out, then lock and tag it","cue":"Rack the breaker fully to open first, then clip your own lock through the hasp and hang your tag on it."},{"id":"verify-zero-energy","title":"Press try-start to prove the breaker is dead","cue":"With the lock and tag on, press the try-start button at the panel and confirm nothing runs."},{"id":"close-isolation-valve","title":"Close the upstream isolation valve","cue":"Turn the isolation valve's wheel closed to cut the flow reaching the screen, on top of the electrical lockout already confirmed."},{"id":"report-locked-and-splash","title":"Report the lockouts and call the splash","cue":"Tell the supervisor: breaker racked, locked and tagged, try-start dead, isolation valve closed, ready to splash."},{"id":"descend-to-screen","title":"Descend the platform's line to the screen","cue":"Follow the platform's descent line down to the screen at a steady pace, keeping the umbilical clear of the frame as you go."},{"id":"screen-condition","title":"Find what is clogging and what is damaged","cue":"Look over the whole screen before touching it: what is only debris to be cleared, and what is actual damage to the frame or the mesh itself."},{"id":"confirm-no-flow","title":"Read the no-flow gauge at the screen itself","cue":"Hold the differential-pressure gauge's sensor flat against the screen face and commit the reading once it settles at zero flow."},{"id":"clear-debris","title":"Clear the debris off the screen face","cue":"Pull the clogging debris free of the mesh and stow it in the debris bag clipped at your side."},{"id":"hold-clean-face","title":"Scrape the screen face clean","cue":"Hold the scraper flat against the mesh and work it steadily across the fouled section until the face reads clean."},{"id":"route-hazards","title":"Find the hazards still at the screen before moving on","cue":"Before switching tools or moving along the face: the torn mesh gap, and whatever is still loose in your own hands."},{"id":"report-screen-clear","title":"Report the screen clear and the bent panel","cue":"Tell the supervisor: debris cleared, face scraped clean, the bent panel logged for the plant's engineers, the mesh gap noted."},{"id":"signal-diver-clear","title":"Hold your signal that you are clear of the screen","cue":"Back away from the screen frame and hold the clear signal steady until the supervisor confirms it before anything at the platform is touched."},{"id":"check-in","title":"Check in at the stage and leave on the supervisor's call","cue":"Back at the stage, clipped on: tell the supervisor how the dive went, the current on the descent and the flow indicator dropping out, and wait for the call to leave the bottom."}]});
